function auditSame(mixed $a,mixed $b):bool {
 if(is_int($a)&&is_int($b))return $a===$b;
 if(is_numeric($a)&&is_numeric($b))return abs((float)$a-(float)$b)<=1e-8*max(1,abs((float)$b));
 if(is_array($b)){if(!is_array($a)||(array_is_list($b)&&count($a)!==count($b)))return false;foreach($b as $k=>$v)if(!array_key_exists($k,$a)||!auditSame($a[$k],$v))return false;return true;}return $a===$b;
}
function audit(string $id,string $section,array $input,array $expected,Closure $run):void {
 global $rows;try{$actual=$run();$pass=auditSame($actual,$expected);}catch(Throwable $e){$actual=['exception'=>get_class($e),'message'=>$e->getMessage()];$pass=false;}
 $rows[]=compact('id','section','input','expected','actual')+['status'=>$pass?'PASS':'FAIL'];echo ($pass?'PASS ':'FAIL ').$id."\n";
}
