class AuditPublicApi extends Wallex {
 public array $calls=[];public bool $fail=false;
 function get(string $path,array $params=[]):array {global $D;$this->calls[]=$path;if(!in_array($path,['/v1/udf/history','/v1/depth'],true))throw new RuntimeException('FORBIDDEN API PATH: '.$path);if($this->fail)throw new RuntimeException('Synthetic transport failure');if($path==='/v1/depth')return ['success'=>true,'result'=>['bid'=>[['price'=>100,'quantity'=>1,'sum'=>100]],'ask'=>[['price'=>101,'quantity'=>1,'sum'=>101]]]];
  $step=$params['resolution']==='1'?60:3600;$r=['s'=>'ok','t'=>[],'o'=>[],'h'=>[],'l'=>[],'c'=>[],'v'=>[]];for($t=$params['from'];$t<=$params['to'];$t+=$step){$r['t'][]=$t;$r['o'][]=100.;$r['h'][]=101.;$r['l'][]=99.;$r['c'][]=100.;$r['v'][]=1.;}return $r;
 }
 function markets():array{$this->calls[]='/v1/markets';return ['BTCUSDT'=>['symbol'=>'BTCUSDT','quoteAsset'=>'USDT','stepSize'=>.001,'tickSize'=>.01,'minQty'=>.001,'minNotional'=>1.]];}
 protected function fetchResponse(string $url,int $remaining):string{throw new RuntimeException('NETWORK FORBIDDEN');}
}
